from django.db import migrations, models


def fix_unapproved_resolved(apps, schema_editor):
    """Before this status existed, "Resolved" meant "submitted, waiting for the Division Head". Move those cases to
    Submitted for approval. Cases a Supervisor accepted stay Resolved."""
    Complaint = apps.get_model("complaints", "Complaint")
    History = apps.get_model("complaints", "StatusHistory")
    for c in Complaint.objects.filter(internal_status="resolved"):
        last = History.objects.filter(complaint=c, new_status="resolved").order_by("-created_at").first()
        if last and last.reason.startswith(("Accepted by supervisor", "Accepted by management")):
            continue
        Complaint.objects.filter(pk=c.pk).update(internal_status="submitted", resolved_at=None)


